import { createHash } from 'node:crypto';
import { PINNED_QURAN_DATASETS } from '../quran/pinned';
import generated from './review-subjects.json';

/**
 * PD-49: what may be reviewed -- every item of the children's Quran content
 * (apps/lessons/src/content/quran/surah-NNN.json, scope `quran-NNN`) and every
 * game mechanic (scope `play`), as the API was built with them. The file is
 * GENERATED by scripts/lessons/lesson-content-subjects.py; CI fails while it is
 * stale. A signature is for an item's CURRENT approval hash only -- the
 * SHA-256 of the canonical JSON of {datasetId, lessonKey, item}, as
 * apps/lessons approvalSha256 -- so change one letter of an item, re-pin the
 * dataset, or copy it to another lesson, and its old signatures no longer
 * describe it.
 *
 * Fail closed: a scope whose entry is malformed, or whose item does not hash
 * to its own approvalSha256, is no scope at all (nothing in it can be signed).
 */
export type Step = 'check' | 'teacher' | 'scholar';

export interface Subject {
  id: string;
  kind: string;
  approvalSha256: string;
  /** The steps it needs before it shows (apps/lessons requiredSteps). */
  requiredSteps: Step[];
  /** The item itself (our own wording and positions), for the reviewer to read. */
  item: Record<string, unknown>;
}

export interface Scope {
  scope: string;
  /** The pinned Quran dataset the content was written against (part of every approval hash). */
  datasetId: string;
  subjects: ReadonlyMap<string, Subject>;
}

export const SCOPE = /^(quran-[0-9]{3}|play)$/;
export const SHA256 = /^[0-9a-f]{64}$/;
const CONTENT_ID = /^[a-z][a-z0-9_]*-[0-9]{3}$/;
const MECHANIC_ID = /^[a-z][a-z0-9_]{1,62}$/;
const STEPS: readonly Step[] = ['check', 'teacher', 'scholar'];

/** Canonical JSON: keys sorted at every level, no whitespace (the same bytes as apps/lessons canonicalJson). */
export function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map(canonicalJson).join(',') + ']';
  const o = value as Record<string, unknown>;
  return '{' + Object.keys(o).sort().map((k) => JSON.stringify(k) + ':' + canonicalJson(o[k])).join(',') + '}';
}

const canonicalSha256 = (value: unknown): string => createHash('sha256').update(canonicalJson(value), 'utf8').digest('hex');

/** What a signature binds (apps/lessons approvalSha256): the item, in its dataset and its lesson (the scope). */
export const approvalSha256 = (datasetId: string, scope: string, item: unknown): string => canonicalSha256({ datasetId, item, lessonKey: scope });

/** Exported for the parity spec with apps/lessons item-hash.vectors.json. */
export { canonicalSha256 };

export function parseScope(raw: unknown): Scope | null {
  const r = raw as { scope?: unknown; datasetId?: unknown; subjects?: unknown } | null;
  if (!r || typeof r !== 'object' || typeof r.scope !== 'string' || !SCOPE.test(r.scope) || !Array.isArray(r.subjects)) return null;
  if (typeof r.datasetId !== 'string' || !PINNED_QURAN_DATASETS.has(r.datasetId)) return null;
  const datasetId = r.datasetId;
  const idPattern = r.scope === 'play' ? MECHANIC_ID : CONTENT_ID;
  const subjects = new Map<string, Subject>();
  for (const s of r.subjects as Array<Partial<Subject>>) {
    if (!s || typeof s.id !== 'string' || !idPattern.test(s.id) || subjects.has(s.id) || typeof s.kind !== 'string') return null;
    if (!Array.isArray(s.requiredSteps) || s.requiredSteps.length === 0 || !s.requiredSteps.every((x) => STEPS.includes(x))) return null;
    if (r.scope === 'play' && s.requiredSteps.includes('check')) return null;
    if (!s.item || typeof s.item !== 'object' || Array.isArray(s.item)) return null;
    if (typeof s.approvalSha256 !== 'string' || !SHA256.test(s.approvalSha256) || approvalSha256(datasetId, r.scope, s.item) !== s.approvalSha256) return null;
    subjects.set(s.id, { id: s.id, kind: s.kind, approvalSha256: s.approvalSha256, requiredSteps: [...s.requiredSteps], item: s.item as Record<string, unknown> });
  }
  return { scope: r.scope, datasetId, subjects };
}

export function parseSubjects(raw: unknown): ReadonlyMap<string, Scope> {
  const scopes = (raw as { scopes?: unknown } | null)?.scopes;
  const out = new Map<string, Scope>();
  if (!Array.isArray(scopes)) return out;
  for (const s of scopes) {
    const parsed = parseScope(s);
    if (parsed && !out.has(parsed.scope)) out.set(parsed.scope, parsed);
  }
  return out;
}

const SCOPES = parseSubjects(generated);

/** A scope as the API was built with it, or null when unknown or it did not verify. */
export function reviewScope(scope: string): Scope | null {
  return SCOPES.get(scope) ?? null;
}
